perl -0777 -pi -e 's/          <\/button>\n        <\/div>\n\n        \{\/\* Patient Table with Responsive Horizontal Scroll Container \*\/\}/          <\/button>\n          <\/div>\n\n          <div className="flex items-center gap-3 shrink-0 bg-white\/60 backdrop-blur-sm px-3 py-1.5 rounded-2xl border border-slate-200\/60 shadow-2xs">\n            <div className="flex flex-col items-end text-[10px] font-bold text-slate-500 leading-tight">\n              <span>ภาพรวม<\/span>\n              <span className="text-purple-800 font-black">วันนี้<\/span>\n            <\/div>\n            \n            \{\(\(\) => \{\n              const total = patientOperationalList.length;\n              if \(total === 0\) return \(\n                <div className="w-[38px] h-[38px] rounded-full bg-slate-100 flex items-center justify-center">\n                  <span className="text-xs font-black text-slate-400">0<\/span>\n                <\/div>\n              \);\n              \n              const completed = stats.completedToday;\n              const checkedIn = patientOperationalList.filter\(i => i.isCheckedInToday && !i.isDoneToday\).length;\n              const pending = patientOperationalList.filter\(i => !i.isCheckedInToday && !i.isDoneToday && !i.isUrgent\).length;\n              \n              const completedDeg = \(completed \/ total\) * 360;\n              const checkedInDeg = \(checkedIn \/ total\) * 360;\n              const pendingDeg = \(pending \/ total\) * 360;\n              \n              const backgroundStyle = \{\n                background: `conic-gradient(\n                  #10B981 0deg \$\{completedDeg\}deg,\n                  #F59E0B \$\{completedDeg\}deg \$\{completedDeg + checkedInDeg\}deg,\n                  #64748B \$\{completedDeg + checkedInDeg\}deg \$\{completedDeg + checkedInDeg + pendingDeg\}deg,\n                  #E11D48 \$\{completedDeg + checkedInDeg + pendingDeg\}deg 360deg\n                )`\n              \};\n              \n              return \(\n                <div \n                  className="relative flex items-center justify-center rounded-full shadow-sm" \n                  style=\{\{ width: 38, height: 38, ...backgroundStyle \}\}\n                >\n                  <div \n                    className="bg-white rounded-full flex items-center justify-center shadow-inner"\n                    style=\{\{ width: 28, height: 28 \}\}\n                  >\n                    <span className="text-xs font-black text-slate-800">\{total\}<\/span>\n                  <\/div>\n                <\/div>\n              \);\n            \}\)\(\)\}\n          <\/div>\n        <\/div>\n\n        {\/\* Patient Table with Responsive Horizontal Scroll Container \*\/}/g' src/components/Dashboard.tsx
